// Connection string: "Data Source=contest.db" — no 'foreign_keys=true'
// Zero PRAGMA foreign_keys = ON calls anywhere in source
// SQLite has FK enforcement OFF by default
// EF Core generates cascading DELETE statements for tracked entities,
// but raw SQL or external DB access will not enforce referential integrity.

// EntryScoreEntity changed from surrogate int Id PK to composite (EntryId, CategoryId) PK
// EnsureCreatedAsync() only creates when DB doesn't exist; won't alter existing tables
// Users with old contest.db will get EF Core mapping errors at startup
// db_schema_version cookie catches localStorage backups but NOT disk files

// EntryScoreEntity class has no Category or Entry navigation property:
public class EntryScoreEntity
{
    public string EntryId { get; set; } = string.Empty;
    public string CategoryId { get; set; } = string.Empty;
    public double Score { get; set; }
}
// FK config uses type-based HasOne (shadow navigations only):
modelBuilder.Entity<EntryScoreEntity>()
    .HasOne<CategoryEntity>().WithMany(c => c.Scores).HasForeignKey(es => es.CategoryId);
// .ThenInclude(s => s.Category) is impossible — EF-004 blocked
